// Copies pdf.js into the app as text, for drawing shared PDF tickets as
// pictures on the phone (src/tickets/PdfPages.tsx). Run after changing the
// pdfjs-dist version: node scripts/embed-pdfjs.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const dir = 'node_modules/pdfjs-dist';
const { version } = JSON.parse(readFileSync(`${dir}/package.json`, 'utf8'));
const lib = readFileSync(`${dir}/build/pdf.min.js`, 'utf8');
const worker = readFileSync(`${dir}/build/pdf.worker.min.js`, 'utf8');
writeFileSync(
  'src/tickets/pdfjs.generated.ts',
  `/* eslint-disable */
// Generated by scripts/embed-pdfjs.mjs from pdfjs-dist ${version}. Do not edit.
// pdf.js is (c) Mozilla and contributors, Apache License 2.0.
export const PDFJS_VERSION = ${JSON.stringify(version)};
export const PDFJS_LIB = ${JSON.stringify(lib)};
export const PDFJS_WORKER = ${JSON.stringify(worker)};
`,
);
console.log(`Embedded pdf.js ${version}`);
